import { useInView } from "./helpers";

export default function ReferralRingSection() {
  const [leftRef, leftVisible] = useInView(0.2);
  const [rightRef, rightVisible] = useInView(0.2);
  const [tlRef, tlVisible] = useInView(0.15);
  const [savingsRef, savingsVisible] = useInView(0.2);

  const TIMELINE_EVENTS = [
    {
      label: "Week 0",
      pos: "above",
      desc: null,
      subDesc: "3 agents profiles flagged for tampering at the time of onboarding.",
    },
    {
      label: "Week 2, Day 1",
      pos: "below",
      desc: "2 weeks and 104 tampered documents later, we noticed something was off.",
      subDesc: null,
    },
    {
      label: "Week 2, Day 2",
      pos: "above",
      desc: null,
      subDesc: "Upon digging deeper, we noticed a pattern with all the profiles referred by Vishal.\n• Every profile had a tampered ID\n• Every ID had the same PIN code\n• Every single profile came through Vishal's reference.",
    },
    {
      label: "Week 2, Day 3",
      pos: "below",
      desc: "The entire fake-account ring was flagged, traced and wiped out.",
      subDesc: null,
    },
  ];

  return (
    <section style={{ padding: "80px 6vw 100px", position: "relative", backgroundColor: "#000", overflow: "hidden" }}>
      <style>{`
        .timeline-grid {
          display: grid;
          grid-template-columns: repeat(4, 1fr);
          position: relative;
          width: 100%;
        }
        .horizontal-line {
          position: absolute;
          top: 50%;
          left: 0;
          right: 0;
          height: 2px;
          background: rgba(255, 255, 255, 1);
          transform: translateY(-50%);
          z-index: 1;
        }
        .timeline-item {
          display: flex;
          flex-direction: column;
          align-items: center;
          position: relative;
          z-index: 2;
          min-height: 280px;
          justify-content: center;
        }
        .timeline-content {
          height: 120px;
          display: flex;
          flex-direction: column;
          justify-content: center;
          width: 100%;
          padding: 0 10px;
        }
        .dot-container {
          height: 40px;
          display: flex;
          align-items: center;
          justify-content: center;
          position: relative;
        }
        .red-dot {
          width: 16px;
          height: 16px;
          background: #e53e3e;
          border-radius: 50%;
          padding:2px;
          box-shadow: 0 0 12px rgba(229, 62, 62, 0.6);
          border: 2px solid #e53e3e;
        }
        @media (max-width: 800px) {
          .timeline-grid { grid-template-columns: 1fr; gap: 40px; padding-left: 40px; }
          .horizontal-line { width: 2px; height: 100%; left: 47px; top: 0; transform: none; }
          .timeline-item { flex-direction: row; min-height: auto; justify-content: flex-start; text-align: left !important; }
          .timeline-content { height: auto; padding: 10px 20px; text-align: left !important; }
          .dot-container { width: 30px; }
          .title-text { font-size: 50px !important; }
        }
      `}</style>

      {/* Story columns */}
      <div style={{ position: "absolute", top: 20, left: -440, zIndex: 0 }}>
          <img src="/assets/Ellipse.png" alt="ellipse" style={{ width: "900px", height: "800px",  }} />
        </div>
      <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 60, maxWidth: 1000, margin: "0 auto 100px", position: "relative", zIndex: 1 }}>


        {/* Left */}
        <div ref={leftRef} style={{ opacity: leftVisible ? 1 : 0, transform: leftVisible ? "translateY(0)" : "translateY(30px)", transition: "opacity 0.7s, transform 0.7s" }}>
          <p style={{ fontFamily: "'Inter',sans-serif", fontSize: "18px", color: "#fff", lineHeight: 1.75, marginBottom: 32 }}>
            Vishal was a delivery agent with <br className="sm:flex hidden"/> Zap Logistics, which was running a <br className="sm:flex hidden"/> generous referral scheme
          </p>
          <div style={{ display: "flex", alignItems: "baseline", gap: 4, marginBottom: 8 }}>
            <span className="title-text" style={{ fontFamily: "'Inter',sans-serif", fontSize: "105px", fontWeight: 700, color: "white", lineHeight: 1 }}>
              <span style={{ color: "#CE1010" }}>₹</span> 3000
            </span>
          </div>
          <p style={{ fontFamily: "'Inter',sans-serif", fontSize: "18px", marginTop: 23, color: "#fff" }}>for every delivery agent referred.<br />Vishal spotted an opportunity.</p>
        </div>

        {/* Right */}
        <div ref={rightRef} style={{ opacity: rightVisible ? 1 : 0, transform: rightVisible ? "translateY(0)" : "translateY(30px)", transition: "opacity 0.7s 0.15s, transform 0.7s 0.15s" }}>
          <p style={{ fontFamily: "'Inter',sans-serif", fontSize: "18px", color: "#fff", fontWeight: 300, lineHeight: 1.75, marginBottom: 20 }}>
            He and his friends found a loophole to bypass the verification process and fabricated
            <span style={{ color: "#CE1010", fontWeight: 700 }}> 107 fake IDs</span> to pocket the referral bonuses.
          </p>
          <p style={{ fontFamily: "'Inter',sans-serif", fontSize: "18px", color: "#fff", fontWeight: 300, lineHeight: 1.75 }}>
            The entire scheme collapsed during onboarding, when every ID linked to his referrals was 
            <span style={{ color: "#CE1010", fontWeight: 700 }}> flagged for fraud.</span>
          </p>
        </div>
      </div>

      {/* Timeline Section */}
      <div ref={tlRef} style={{ maxWidth: 1100, margin: "0 auto 100px", opacity: tlVisible ? 1 : 0, transform: tlVisible ? "translateY(0)" : "translateY(30px)", transition: "opacity 0.7s, transform 0.7s" }}>
        <h2 className="title-text" style={{ fontFamily: "'Inter',sans-serif", fontSize: "105px", fontWeight: 700, color: "white", textAlign: "center", marginBottom: 60 }}>
          Timeline of events
        </h2>

        <div className="timeline-grid">
          <div className="horizontal-line text-white"></div>

          {TIMELINE_EVENTS.map((ev, i) => (
            <div key={i} className="timeline-item">

              {/* TOP SLOT */}
              <div className="timeline-content" style={{ textAlign: "center", justifyContent: "flex-end" }}>
                {ev.pos === "above" ? (
                   <p style={{ color: "#CE1010", fontWeight: 700, fontSize: 16, margin: "0 0 10px" }}>{ev.label}</p>
                ) : (
                   <p style={{ color: "rgba(255,255,255,1)", fontSize: 14, lineHeight: 1.6 }}>{ev.desc}</p>
                )}
              </div>

              {/* CENTER SLOT (DOT) */}
              <div className="dot-container">
                <div className="red-dot"></div>
              </div>

              {/* BOTTOM SLOT */}
              <div className="timeline-content" style={{ textAlign: "center", justifyContent: "flex-start" }}>
                {ev.pos === "above" ? (
                   <p style={{ color: "rgba(255,255,255,1)", fontSize: 16, lineHeight: 1.6, whiteSpace: "pre-line", textAlign: "left" }}>{ev.subDesc}</p>
                ) : (
                   <p style={{ color: "#CE1010", fontWeight: 700, fontSize: 16, margin: "10px 0 0" }}>{ev.label}</p>
                )}
              </div>

            </div>
          ))}
        </div>
      </div>

      {/* Savings impact */}
      <div ref={savingsRef} style={{ maxWidth: 1000, margin: "0 auto", textAlign: "center", opacity: savingsVisible ? 1 : 0, transform: savingsVisible ? "translateY(0)" : "translateY(30px)", transition: "opacity 0.7s, transform 0.7s" }}>
        <p style={{              fontFamily: "'Inter',sans-serif", fontSize: "clamp(22px,2.5vw,36px)", color: "rgba(255,255,255,0.8)", marginBottom: 16 }}>
          This single catch saved <span style={{ color: "#CE1010", fontWeight: 700 }}>Zap Logistics</span> nearly
        </p>
        <h2 style={{  fontFamily: "'Inter',sans-serif", fontSize: "105px", fontWeight: 700, color: "white", lineHeight: 1.0, margin: "0 0 24px" }}>
          <span style={{ color: "#CE1010" }}>₹</span>16 lakh in potential<br />theft and fraud
        </h2>
        <p style={{ fontFamily: "'Inter',sans-serif", fontSize: "20px", color: "rgba(255,255,255,0.6)", lineHeight: 1.75, maxWidth: 700, margin: "0 auto" }}>
